/**
 * Intentionally different load-bearing silhouettes for the collection.
 *
 * Every visible triangle is an actual right triangle; all pairs of filled
 * pieces have disjoint interiors. Nothing is drawn merely to imply a
 * Pythagoras question that cannot be solved from the displayed lengths.
 *
 * The small helpers below only attach on the OUTSIDE of their owner's
 * edge. Individual challenges choose their own supports, gaps and
 * dependency relations; they are not generated by repeating a chain.
 */
const p=(x,y)=>({x,y});
const length=(a,b)=>Math.hypot(b.x-a.x,b.y-a.y);
const vec=(a,b)=>p(b.x-a.x,b.y-a.y);
const cross=(a,b)=>a.x*b.y-a.y*b.x;
const middle=(a,b)=>p((a.x+b.x)/2,(a.y+b.y)/2);
const average=shape=>p(shape.pts.reduce((s,q)=>s+q.x,0)/shape.pts.length,
  shape.pts.reduce((s,q)=>s+q.y,0)/shape.pts.length);
const colors=[
  "#d6b06c","#7da7a9","#c48670","#9ea8a0","#a6a0bd",
  "#8fafa0","#c7a385","#91a9c0","#9ca880","#bb969b"
];
const roman=["I","II","III","IV","V","VI","VII","VIII","IX","X"];
const given=(a,b)=>({a,b,value:length(a,b)});
const tri=(id,pts,right,givens=[])=>({
  id,pts,right,color:colors[roman.indexOf(id)%colors.length],givens
});
const rect=(id,pts,diagonal=given(pts[0],pts[2]),suppressLabels=[])=>({
  id,pts,color:id==="R1"?"#d7cfb7":"#c1c6b7",
  diagonals:[{a:pts[0],b:pts[2]}],givens:[diagonal],
  suppressLabels,rightAngles:true
});
const opposite=(owner,a,b,origin,leg)=>{
  const v=vec(a,b),unit=length(a,b),mid=middle(a,b);
  const sign=cross(v,vec(mid,average(owner)))>=0?-1:1;
  return p(origin.x-sign*v.y/unit*leg,origin.y+sign*v.x/unit*leg);
};
const attach=(owner,a,b,at,leg,id)=>{
  const origin=at==="a"?a:b;
  const c=opposite(owner,a,b,origin,leg);
  return tri(id,[a,b,c],at==="a"?0:1,[given(origin,c)]);
};
const hypotenuse=t=>t.pts.filter((_,i)=>i!==t.right);
const relation=(whole,first,second,label="TWO SHARED SECTIONS")=>({
  whole:{a:whole[0],b:whole[1]},
  parts:[{a:first[0],b:first[1]},{a:second[0],b:second[1]}],
  label
});
const equal=(a,b,c,d)=>[[{a,b},{a:c,b:d}]];
const finish=(info,triangles,rectangles,target,floor,options={})=>({
  ...info,...options,triangles,rectangles,
  fallOrder:options.fallOrder||[...triangles.map(t=>t.id),...rectangles.map(r=>r.id)],
  target:{a:target[0],b:target[1]},
  floor:{a:floor[0],b:floor[1]},solution:length(...target)
});
function architecture(family,summary,features){
  return {family,summary,features};
}

/* 02 | THE PROJECTING EDGE
 * The long cantilever projects beyond the 5–12–13 base. Its two cap
 * triangles grow off DIFFERENT edges, not off one repeated hypotenuse.
 * The main target requires the 4 cm projection to be added before
 * its upper supporting leg can be recovered by subtraction.
 */
export function makeCantileverChallenge(info){
  const P=p(0,0),Q=p(12,0),R=p(12,5);
  const T=p(12*17/13,5*17/13); // 13+4 support, exactly collinear
  const U=opposite({pts:[P,Q,R]},P,T,T,10);
  const I=tri("I",[P,Q,R],1,[given(P,Q),given(Q,R)]);
  const II=tri("II",[P,T,U],1,[given(P,U)]); // given sqrt(389)
  const III=attach(II,P,U,"b",4,"III");
  const IV=attach(II,T,U,"b",5,"IV");
  const overhang={a:R,b:T,value:4,label:"PROJECTING OVERHANG"};
  return finish(info,[I,II,III,IV],[],hypotenuse(IV),[P,Q],{
    overhang:{a:R,b:T,value:4},
    extraSegments:[overhang],
    lengthRelations:[relation([P,T],[P,R],[R,T],"PROJECTING OVERHANG")],
    tags:["Cantilever","Two upper arms","Overhang addition"],
    topology:"cantilever-with-two-arms",
    architecture:architecture("cantilever","A projecting shoulder with two unequal upper arms",
      ["one floor support","projecting overhang","two different attachment edges"])
  });
}

/* 04 | SPLIT & PROJECT
 * A completely different silhouette from Twin Paths: TWO grounded
 * piers with a gap beneath a single upper beam and a 3 cm free end.
 * Floor-length subtraction -> equal upper span -> whole+overhang ->
 * Pythagoras for the final roof. Both piers also have their own
 * independent right-triangle calculation.
 */
export function makeSuspendedProjectChallenge(info){
  const A=p(0,0),B=p(6,0),C=p(6,8);
  const D=p(18,0),E=p(27,0),F=p(18,8);
  const G=p(21,8),H=p(21,16),topEnd=p(18,8),groundGapEnd=p(18,0);
  const I=tri("I",[A,B,C],1,[given(A,B),given(A,C)]);
  const II=tri("II",[D,E,F],0,[given(D,E),given(E,F)]);
  const III=tri("III",[C,G,H],1,[given(G,H)]);
  const floorGap=[B,D],upperGap=[C,F];
  const ex=[
    {a:A,b:E,value:27,label:"FOUNDATION SPAN"},
    {a:F,b:G,value:3,label:"PROJECTING OVERHANG"}
  ];
  return finish(info,[I,II,III],[],hypotenuse(III),[A,E],{
    extraSegments:ex,overhang:{a:F,b:G,value:3},
    lengthRelations:[
      relation([A,E],[A,D],[D,E],"FOUNDATION SPAN"),
      relation([A,D],[A,B],[B,D],"FOUNDATION SPAN"),
      relation([C,G],[C,F],[F,G],"PROJECTING OVERHANG")
    ],
    equalSideGroups:equal(floorGap[0],floorGap[1],upperGap[0],upperGap[1]),
    tags:["Two floor supports","Open gap","Measured projection","Matching spans"],
    topology:"split-foundations-cantilever",
    architecture:architecture("split foundations","A cantilever sits across two grounded supports",
      ["two independent ground pieces","visible gap","projecting end","matching parallel spans"])
  });
}

/* 05 | THE GEOMETER'S LABYRINTH
 * Two lower walls enclose a triangular opening. Two different upward
 * branches meet at the ridge; the final roof lies across their sum.
 * The two independent hypotenuse deductions are needed to find the
 * roof's 12 cm horizontal leg (7+5).
 */
export function makeForkAndRejoinChallenge(info){
  const A=p(0,0),B=p(6,0),C=p(6,8);
  const D=p(18,0),E=p(27,0),F=p(18,8);
  const M=p(13,8),roof=p(18,17);
  const I=tri("I",[A,B,C],1,[given(A,B),given(A,C)]);
  const II=tri("II",[D,E,F],0,[given(D,E),given(E,F)]);
  const III=tri("III",[B,C,M],1,[given(B,M)]);
  const IV=tri("IV",[D,F,M],1,[given(D,M)]);
  const V=tri("V",[C,F,roof],1,[given(F,roof)]);
  return finish(info,[I,II,III,IV,V],[],hypotenuse(V),[A,E],{
    lengthRelations:[relation([C,F],[C,M],[M,F])],
    spanHighlight:{whole:{a:C,b:F},parts:[{a:C,b:M},{a:M,b:F}]},
    tags:["Two routes","Hollow arch","Split roof","Combine 7 + 5"],
    topology:"forked-arch-rejoining-roof",
    architecture:architecture("fork and rejoin","Two calculation routes support the final roof",
      ["two grounded walls","triangular central opening","rejoined split side"])
  });
}

/* 06 | THE GREAT PILE UP
 * Two point-supported abutments, a visibly EMPTY span beneath the
 * bridging right triangle, then two distinct further roof pitches.
 */
export function makeBridgeChallenge(info){
  const A=p(0,0),B=p(5,0),C=p(5,12);
  const D=p(17,0),E=p(22,0),F=p(17,12);
  const T=p(17,17);
  const I=tri("I",[A,B,C],1,[given(A,B),given(A,C)]);
  const II=tri("II",[D,E,F],0,[given(D,E),given(E,F)]);
  const III=tri("III",[C,F,T],1,[given(F,T),given(C,T)]);
  const IV=attach(III,C,T,"b",6,"IV");
  const [H1,H2]=hypotenuse(IV);
  const V=attach(IV,H1,H2,"b",5,"V");
  return finish(info,[I,II,III,IV,V],[],hypotenuse(V),[A,E],{
    tags:["Two abutments","Clear underside","Bridge span","Upper roof"],
    topology:"open-bridge-rising-peak",
    architecture:architecture("open bridge","A triangular beam spans two separate piers over a full open bay",
      ["two grounded piers","unsupported open bay","one spanning beam","asymmetric roof"])
  });
}

/* 07 | THE NINE MUSES
 * Three separate footings support TWO parallel intermediate roofs.
 * Their outer uprights are translated copies, allowing a genuine
 * matching-side step to unlock the upper beam. The last roof rises
 * above this rejoined tier rather than fanning from one old vertex.
 */
export function makeTerracedMusesChallenge(info){
  const A=p(-6,0),B=p(0,0),C=p(0,8);
  const D=p(12,0),E=p(18,0),F=p(12,8);
  const G=p(24,0),H=p(31,0),I0=p(24,8);
  const J=p(12,13),K=p(24,13);
  const triangles=[
    tri("I",[A,B,C],1,[given(A,B),given(A,C)]),
    tri("II",[D,E,F],0,[given(D,E),given(E,F)]),
    tri("III",[G,H,I0],0,[given(G,H),given(H,I0)]),
    tri("IV",[C,F,J],1,[given(F,J),given(C,J)]),
    tri("V",[F,I0,K],1,[given(I0,K)])
  ];
  const VI=attach(triangles[3],C,J,"b",6,"VI");
  const VII=attach(triangles[4],F,K,"b",6,"VII");
  triangles.push(VI,VII);
  const L=VI.pts[2],M=VII.pts[2],N=p(M.x,M.y+7);
  const VIII=tri("VIII",[L,M,N],1,[given(M,N)]);
  const IX=attach(VIII,L,N,"b",9,"IX");
  triangles.push(VIII,IX);
  // The two intermediate roof lengths are genuinely equal by
  // construction. The upper span is their translated equal.
  const equalSideGroups=[
    [{a:C,b:F},{a:F,b:I0}],
    [{a:C,b:F},{a:L,b:M}]
  ];
  return finish(info,triangles,[],hypotenuse(IX),[A,H],{
    equalSideGroups,
    tags:["Three foundations","Terraced twin roofs","Matching lengths","Upper rejoin"],
    topology:"three-foundation-twin-terrace",
    architecture:architecture("tiered terraces","Three foundations rise through two adjoining roof tiers",
      ["three ground contacts","two intermediate spans","upper shared bridge","ascending cap"])
  });
}

/* 08 | THE MARBLE TERRACE
 * A broad RECTANGLE is a real base platform. Two floor braces
 * touch it from the sides, two different roof pitches rise from a
 * 4+8 split, and the two upper arms form offset terraces.
 */
export function makePlatformTerraceChallenge(info){
  const A=p(0,0),B=p(12,0),C=p(12,5),D=p(0,5);
  const L=p(-6,0),R=p(18,0),M=p(4,5);
  const roofL=p(4,9),roofR=p(12,9);
  const R1=rect("R1",[A,B,C,D],given(A,C),
    [{a:A,b:B},{a:B,b:C}]);
  const triangles=[
    tri("I",[L,A,D],1,[given(L,A),given(L,D)]),
    tri("II",[B,C,R],0,[given(B,R),given(C,R)]),
    tri("III",[D,M,roofL],1,[given(M,roofL),given(D,roofL)]),
    tri("IV",[M,C,roofR],1,[given(C,roofR)])
  ];
  const V=attach(triangles[2],D,roofL,"b",4,"V");
  const VI=attach(triangles[3],M,roofR,"b",6,"VI");
  triangles.push(V,VI);
  const VII=attach(V,V.pts[1],V.pts[2],"b",3,"VII");
  const VIII=attach(VI,VI.pts[2],VI.pts[0],"a",6,"VIII");
  triangles.push(VII,VIII);
  return finish(info,triangles,[R1],hypotenuse(VIII),[L,R],{
    lengthRelations:[relation([D,C],[D,M],[M,C])],
    spanHighlight:{whole:{a:D,b:C},parts:[{a:D,b:M},{a:M,b:C}]},
    tags:["Rectangle foundation","Route choice","Two supporting braces","Upper terrace"],
    routeChallenge:{par:7,startTriangle:"II"},
    topology:"rectangle-platform-stepped-ridges",
    rectangleReasoning:true,
    fallOrder:["I","R1","II","III","IV","V","VI","VII","VIII"],
    architecture:architecture("stepped platform","A rectangle and alternate braces support two terraces, but only one upper branch leads to x",
      ["horizontal stone platform","alternative grounded braces","split roof","optional left peak","seven-check route"])
  });
}

/* 09 | THE ACROPOLIS
 * TWO plinths rise from independently solvable foundations with a
 * narrow connector over the open bay. The high beam is exactly
 * 12 + 12 because its halves match the TWO rectangle roofs.
 * Thus both diagonals are prerequisites for the final 7–24–25 roof.
 */
export function makeTwinPlinthAcropolis(info){
  const A=p(0,0),B=p(12,0),C=p(12,6),D=p(0,6);
  const E=p(22,0),F=p(34,0),G=p(34,8),H=p(22,8);
  const R1=rect("R1",[A,B,C,D],given(A,C),
    [{a:A,b:B},{a:B,b:C}]);
  const R2=rect("R2",[E,F,G,H],given(E,G),
    [{a:E,b:F},{a:E,b:H}]);
  const triangles=[
    tri("I",[A,D,p(-5,6)],1,[given(A,p(-5,6)),given(D,p(-5,6))]),
    tri("II",[p(-11,0),p(-5,0),p(-5,6)],1,
      [given(p(-11,0),p(-5,0)),given(p(-11,0),p(-5,6))]),
    tri("III",[F,G,p(40,8)],1,[given(F,p(40,8)),given(G,p(40,8))]),
    tri("IV",[p(40,0),p(46,0),p(40,8)],0,
      [given(p(40,0),p(46,0)),given(p(46,0),p(40,8))]),
    tri("V",[C,p(22,6),H],1,[given(C,H),given(p(22,6),H)]),
    tri("VI",[D,C,p(12,11)],1,[given(C,p(12,11))]),
    tri("VII",[H,G,p(34,11)],1,[given(G,p(34,11))])
  ];
  const VIII=attach(triangles[5],D,p(12,11),"b",13,"VIII");
  const IX=attach(triangles[6],H,p(34,11),"b",Math.sqrt(153),"IX");
  triangles.push(VIII,IX);
  const J=VIII.pts[2],K=IX.pts[2];
  const M=p((J.x+K.x)/2,J.y),roof=p(K.x,K.y+7);
  const X=tri("X",[J,K,roof],1,[given(K,roof)]);
  triangles.push(X);
  const equalSideGroups=[
    [{a:D,b:C},{a:J,b:M}],
    [{a:H,b:G},{a:M,b:K}]
  ];
  return finish(info,triangles,[R1,R2],hypotenuse(X),[p(-11,0),p(46,0)],{
    equalSideGroups,
    lengthRelations:[relation([J,K],[J,M],[M,K])],
    spanHighlight:{whole:{a:J,b:K},parts:[{a:J,b:M},{a:M,b:K}]},
    tags:["Twin plinths","Two independent diagonals","High bridge","7–24–25 finale"],
    topology:"two-plinths-grand-arch",
    rectangleReasoning:true,
    fallOrder:["II","I","R1","IV","III","R2","V","VI","VII","VIII","IX","X"],
    architecture:architecture("twin plinth acropolis",
      "Two separate rectangle calculations support the final high bridge",
      ["two floor platforms","open central bay","two diagonal dependencies",
       "upper meeting beam","two equal halves"])
  });
}
